// ── CSV writer ─────────────────────────────────────────────────────────
const COLS = [
  "#",
  "video_id",
  "subject",
  "category",
  "tier",
  "shot_type",
  "aspect_ratio",
  "duration_sec",
  "use_case",
  "prompt",
  "camera_and_movement",
  "lighting_and_time_of_day",
  "audio_and_sound_design",
  "reference_url",
  "must_show",
  "must_avoid",
  "anti_fabrication_note",
  "status",
];

function csvCell(v) {
  const s = v === null || v === undefined ? "" : String(v);
  // Strip stray CR/LF and tab, then escape internal double quotes.
  const clean = s.replace(/\r/g, "").replace(/\n/g, " ").replace(/\t/g, " ");
  return `"${clean.replace(/"/g, '""')}"`;
}

const header = COLS.map(csvCell).join(",");
const rows = VIDEOS.map((v, i) => {
  const row = {
    "#": i + 1,
    video_id: v.video_id,
    subject: v.subject,
    category: v.category,
    tier: v.tier,
    shot_type: v.shot_type,
    aspect_ratio: v.aspect_ratio,
    duration_sec: v.duration_sec,
    use_case: v.use_case,
    prompt: v.prompt,
    camera_and_movement: v.camera_and_movement,
    lighting_and_time_of_day: v.lighting_and_time_of_day,
    audio_and_sound_design: v.audio_and_sound_design,
    reference_url: v.reference_url,
    must_show: v.must_show,
    must_avoid: v.must_avoid,
    anti_fabrication_note: v.anti_fabrication_note,
    status: "Pending",
  };
  return COLS.map((c) => csvCell(row[c])).join(",");
});

const csv = [header, ...rows].join("\n") + "\n";

const out = path.join(process.cwd(), "data", "luxury", "video-production-brief.csv");
writeFileSync(out, csv, "utf-8");

console.log(`✓ Wrote ${VIDEOS.length} videos to ${out}`);
const byCat = VIDEOS.reduce((acc, v) => { acc[v.category] = (acc[v.category] ?? 0) + 1; return acc; }, {});
console.log("  by category:", byCat);
const totalSec = VIDEOS.reduce((acc, v) => acc + v.duration_sec, 0);
console.log(`  total runtime: ${totalSec}s (${Math.round(totalSec/60*10)/10} min)`);
